<script setup>
import {useArcade} from './stores/arcade'
import {partnerTheme} from './data/evolutions'
import {ref,watch,onMounted,onUnmounted} from 'vue'
import NewDungeonPopup from './components/NewDungeonPopup.vue'
import GiftCenter from './components/GiftCenter.vue'
import AttendancePopup from './components/AttendancePopup.vue'
import PageBoundary from './components/PageBoundary.vue'
import ActivityPopups from './components/ActivityPopups.vue'
import {useActivity} from './stores/activity'
import {useQuests} from './stores/quests'
import {useRoom} from './stores/room'
import MailArrivalPopup from './components/MailArrivalPopup.vue'
import QuestionComposer from './components/QuestionComposer.vue'
import {useMessages} from './stores/messages'
import {useLearning} from './stores/learning'
import PartnerImage from './components/PartnerImage.vue'
import {useRouter} from 'vue-router'
import {api} from './lib/api'
const router=useRouter(),sidebarOpen=ref(false),openMenu=ref(''),logoutDialog=ref(null),logoutBusy=ref(false),logoutError=ref('');let presenceTimer
watch(()=>router.currentRoute.value.fullPath,()=>sidebarOpen.value=false)
watch(sidebarOpen,()=>openMenu.value='')
function hoverMenu(id){if(window.matchMedia('(hover: hover)').matches)openMenu.value=id}
function leaveMenu(event){if(window.matchMedia('(hover: hover)').matches)openMenu.value=''}
function sidebarKey(event){if(event.key==='Escape')sidebarOpen.value=false}
function presence(){if(s.user?.role==='student')api('/presence',{method:'POST',body:{active:document.visibilityState==='visible'}}).catch(()=>{})}
async function confirmLogout(){if(logoutBusy.value)return;logoutBusy.value=true;logoutError.value='';try{await s.logout();logoutDialog.value?.close();await router.replace('/account')}catch(e){logoutError.value=e.message}finally{logoutBusy.value=false}}
const s=useArcade(),learning=useLearning(),messages=useMessages(),activity=useActivity(),quests=useQuests();let mailTimer
function updateMail(){presence();if(s.user&&document.visibilityState==='visible'){messages.refresh();activity.refresh();quests.refresh()}}
watch(()=>[s.user?.role,s.partner.id,s.partner.stage],()=>{document.documentElement.dataset.partner=s.user?.role==='student'?partnerTheme(s.partner):'system'},{immediate:true})
watch(()=>!!s.user,value=>document.documentElement.classList.toggle('auth-mode',!value),{immediate:true})
watch(()=>s.user?.id,()=>{learning.reset();messages.reset();activity.reset();quests.reset();useRoom().reset();clearInterval(mailTimer);if(s.user){updateMail();mailTimer=setInterval(updateMail,15000)}})
onMounted(()=>{document.addEventListener('keydown',sidebarKey);presence();presenceTimer=setInterval(presence,30000);if(s.user){updateMail();mailTimer=setInterval(updateMail,15000)}document.addEventListener('visibilitychange',updateMail);window.addEventListener('spokemon-points-refresh',updateMail)})
onUnmounted(()=>{document.removeEventListener('keydown',sidebarKey);clearInterval(presenceTimer);clearInterval(mailTimer);document.removeEventListener('visibilitychange',updateMail);window.removeEventListener('spokemon-points-refresh',updateMail)})
</script>
<template><NewDungeonPopup/><AttendancePopup/><ActivityPopups/><MailArrivalPopup/><div :class="['shell',{'auth-shell':!s.user}]"><header v-if="s.user"><RouterLink class="brand brand-logo" :to="s.user?.role==='admin'?'/admin':'/home'" :aria-label="s.user?.role==='admin'?'Spokemon 관리자 페이지로':'Spokemon 메인으로'"><img class="site-logo" src="/images/pokemon-logo.png" alt="Spokemon" width="1869" height="854" fetchpriority="high"/><span class="brand-title">Spokemon</span></RouterLink><div class="wallet"><template v-if="s.user.role==='student'"><RouterLink to="/pet" class="partner-wallet"><PartnerImage size="tiny"/> Lv.{{s.level}}</RouterLink><RouterLink to="/quests" class="profile-link quest-wallet">📖 퀘스트<i v-if="quests.ready" class="quest-ready-light" :aria-label="'수령할 퀘스트 '+quests.ready+'개'"/></RouterLink><span>🪙 <b>{{s.data.coins.toLocaleString()}}</b></span></template><button v-if="s.user.role==='admin'" class="profile-link admin-logout" @click="logoutDialog.showModal()">{{s.user.nickname}}님 ⏻</button><RouterLink v-else to="/account" class="profile-link">{{s.user.nickname}}님 ⚙</RouterLink></div></header>
 <div v-if="s.user" class="navigation-row"><button v-if="s.user.role==='student'" class="menu-toggle" :aria-expanded="sidebarOpen" aria-controls="student-navigation" @click="sidebarOpen=!sidebarOpen">☰ 메뉴</button><nav v-else><RouterLink to="/admin">관리자 페이지</RouterLink><RouterLink to="/workshop">공유 문제 관리</RouterLink></nav><div class="question-toolbar"><RouterLink v-if="s.user.role==='admin'" to="/sloud" class="button sloud-shortcut">Sloud</RouterLink><template v-if="s.user.role==='student'"><QuestionComposer/><GiftCenter/></template></div></div>
 <template v-if="s.user?.role==='student'&&sidebarOpen"><div class="student-sidebar-shade" @click="sidebarOpen=false"></div><aside id="student-navigation" class="student-sidebar" aria-label="사용자 메뉴" @keydown.esc="sidebarOpen=false"><div class="sidebar-title"><b>모험 메뉴</b><button aria-label="메뉴 닫기" @click="sidebarOpen=false">✕</button></div><nav class="sidebar-menu-body" @click="$event.target.closest('a')&&(sidebarOpen=false)"><RouterLink to="/guide" class="sidebar-main-link sidebar-guide-link" aria-label="Spokemon 이용 가이드" @click="sidebarOpen=false"><img src="/images/pokemon-logo.png" alt="" width="1869" height="854"/><span>이용 가이드</span></RouterLink><section class="sidebar-menu-group" @mouseenter="hoverMenu('study')" @mouseleave="leaveMenu"><div class="sidebar-group-heading"><RouterLink to="/student" class="sidebar-main-link" @focus="openMenu='study'">내 학습</RouterLink><button class="submenu-toggle" :aria-expanded="openMenu==='study'" aria-controls="submenu-study" aria-label="내 학습 하위 메뉴" @click="openMenu=openMenu==='study'?'':'study'">{{openMenu==='study'?'⌃':'⌄'}}</button></div><div v-if="openMenu==='study'" id="submenu-study" class="sidebar-submenu"><RouterLink to="/workshop">문제 제작소</RouterLink><RouterLink to="/sloud">Sloud(게시판)</RouterLink></div></section><RouterLink to="/quiz" class="sidebar-main-link">문제풀기(퀴즈타임)</RouterLink><section class="sidebar-menu-group" @mouseenter="hoverMenu('games')" @mouseleave="leaveMenu"><button class="sidebar-games-toggle" :aria-expanded="openMenu==='games'" aria-controls="submenu-games" @click="openMenu=openMenu==='games'?'':'games'">게임하기 <span>{{openMenu==='games'?'⌃':'⌄'}}</span></button><div v-if="openMenu==='games'" id="submenu-games" class="sidebar-submenu"><RouterLink to="/cards">카드 뒤집기</RouterLink><RouterLink to="/hidden">숨은그림 찾기</RouterLink><RouterLink to="/python-dungeon">코딩 던전</RouterLink></div></section><section class="sidebar-menu-group" @mouseenter="hoverMenu('pet')" @mouseleave="leaveMenu"><div class="sidebar-group-heading"><RouterLink to="/pet" class="sidebar-main-link" @focus="openMenu='pet'">마이 리틀 펫</RouterLink><button class="submenu-toggle" :aria-expanded="openMenu==='pet'" aria-controls="submenu-pet" aria-label="마이 리틀 펫 하위 메뉴" @click="openMenu=openMenu==='pet'?'':'pet'">{{openMenu==='pet'?'⌃':'⌄'}}</button></div><div v-if="openMenu==='pet'" id="submenu-pet" class="sidebar-submenu"><RouterLink to="/collection">포켓몬 도감</RouterLink></div></section><RouterLink to="/pet/mailbox" class="sidebar-main-link">내 쪽지함 <b v-if="messages.unread">{{messages.unread}}</b></RouterLink></nav><div class="sidebar-account-actions"><RouterLink to="/account" @click="sidebarOpen=false">회원정보</RouterLink><button @click="sidebarOpen=false;logoutDialog.showModal()">로그아웃</button></div></aside></template><p v-if="s.storageError" class="notice" role="alert">{{s.storageError}}</p><main><PageBoundary><RouterView :key="s.user?.id||'guest'" /></PageBoundary></main><footer v-if="s.user"><span>✦ Spokemon</span><span>작은 휴식, 즐거운 한 판 · 서버에 안전하게 저장됩니다</span></footer><dialog ref="logoutDialog" class="logout-dialog" aria-label="로그아웃 확인"><h2>로그아웃 하시겠습니까?</h2><p v-if="logoutError" role="alert">{{logoutError}}</p><div class="toolbar"><button class="light" :disabled="logoutBusy" @click="logoutDialog.close()">취소</button><button :disabled="logoutBusy" @click="confirmLogout">{{logoutBusy?'로그아웃 중…':'로그아웃'}}</button></div></dialog></div></template>

<style scoped>
.quest-wallet{position:relative}.quest-ready-light{position:absolute;top:-5px;right:-5px;display:block;width:13px;height:13px;border-radius:50%;background:#ff263f;border:2px solid white;box-shadow:0 0 0 1px #a50925,0 0 9px #ff263faa;pointer-events:none}
</style>

<style scoped>
.navigation-row{justify-content:space-between}.question-toolbar{margin-left:auto;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.wallet{display:flex;align-items:center;gap:8px}.menu-toggle{min-width:100px}
.question-toolbar>a,.question-toolbar :deep(.gift-center-launch),.question-toolbar :deep(.question-launch){box-sizing:border-box!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;height:42px!important;min-height:42px!important;line-height:1.2!important;padding:8px 13px!important;font-size:12px!important;margin:0!important}
.student-sidebar-shade{position:fixed;inset:0;background:#13263d80;z-index:90}
.student-sidebar{position:fixed;left:0;top:0;bottom:0;z-index:91;width:min(310px,86vw);padding:18px 16px;display:flex;flex-direction:column;overflow:hidden;box-sizing:border-box;background:var(--rpg-paper,#fff);border-right:3px solid var(--rpg-edge);box-shadow:8px 0 24px #14273a40;color:var(--rpg-ink)}
.sidebar-title{display:flex;align-items:center;justify-content:space-between;flex:none;margin-bottom:18px;gap:12px;font-size:14px}.sidebar-title button{width:40px;height:40px;min-height:40px;padding:0;flex:none}
.student-sidebar .sidebar-menu-body{display:flex;flex-direction:column;gap:10px;overflow:auto;flex:1;min-height:0;margin:0;padding:2px 4px 16px 2px;border:0;white-space:normal}
.sidebar-menu-group{margin:0;min-width:0}
/* Every top-level entry is one 46px surface, whether it is a link or a disclosure. */
.student-sidebar .sidebar-group-heading,.student-sidebar .sidebar-menu-body>.sidebar-main-link,.student-sidebar .sidebar-games-toggle,.student-sidebar .sidebar-account-actions>a,.student-sidebar .sidebar-account-actions>button{display:flex!important;align-items:center!important;justify-content:flex-start!important;width:100%!important;height:46px!important;min-height:46px!important;box-sizing:border-box!important;margin:0!important;padding:0 12px!important;gap:8px;border:2px solid var(--rpg-edge)!important;border-radius:5px!important;background:var(--rpg-soft)!important;background-image:none!important;color:var(--rpg-ink)!important;box-shadow:0 3px 0 var(--rpg-shadow)!important;font-family:inherit!important;font-size:13px!important;font-weight:700!important;line-height:1.4!important;text-align:left!important;letter-spacing:0!important;text-shadow:none!important;transform:none!important;outline:none!important;transition:background .15s}
.student-sidebar .sidebar-group-heading{padding:0!important;gap:0}
.student-sidebar .sidebar-group-heading>.sidebar-main-link{display:flex!important;align-items:center!important;flex:1;min-width:0;height:100%!important;min-height:0!important;width:auto!important;box-sizing:border-box;margin:0!important;padding:0 12px!important;border:0!important;border-radius:3px 0 0 3px!important;box-shadow:none!important;outline:none!important;background:transparent!important;background-image:none!important;color:inherit!important;font-size:13px!important;font-weight:700!important;line-height:1.4!important;text-shadow:none!important;transform:none!important}
.student-sidebar .submenu-toggle{display:flex!important;align-items:center!important;justify-content:center!important;align-self:stretch;flex:0 0 40px;width:40px!important;height:100%!important;min-height:0!important;margin:0!important;padding:0!important;border:0!important;border-radius:0 3px 3px 0!important;box-shadow:none!important;background:transparent!important;background-image:none!important;color:inherit!important;font-size:0!important;text-shadow:none!important;transform:none!important;outline:none!important}
.student-sidebar .sidebar-games-toggle{padding-right:0!important;justify-content:space-between!important}.sidebar-games-toggle>span{display:flex;align-items:center;justify-content:center;align-self:stretch;flex:0 0 40px;font-size:0}
.student-sidebar .submenu-toggle::after,.student-sidebar .sidebar-games-toggle>span::after{content:''!important;display:block;width:7px;height:7px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(45deg);margin-top:-4px}
.student-sidebar .submenu-toggle[aria-expanded="true"]::after,.student-sidebar .sidebar-games-toggle[aria-expanded="true"]>span::after{transform:rotate(225deg);margin-top:4px}
.student-sidebar a::before,.student-sidebar .sidebar-games-toggle::before,.student-sidebar .sidebar-account-actions>button::before{content:none!important;display:none!important}
.student-sidebar .sidebar-group-heading:has(>.router-link-exact-active),.student-sidebar .sidebar-menu-body>.router-link-exact-active,.student-sidebar .sidebar-account-actions>.router-link-exact-active{background:var(--rpg-paper)!important;box-shadow:inset 3px 0 var(--rpg-edge),0 3px var(--rpg-shadow)!important}
.student-sidebar .sidebar-group-heading:hover,.student-sidebar .sidebar-menu-body>.sidebar-main-link:hover,.student-sidebar .sidebar-games-toggle:hover,.student-sidebar .sidebar-account-actions>a:hover,.student-sidebar .sidebar-account-actions>button:hover{background:var(--rpg-paper)!important}
.student-sidebar a:focus-visible,.student-sidebar button:focus-visible{outline:2px solid var(--rpg-ink)!important;outline-offset:-5px!important}
.sidebar-submenu{margin:9px 0 2px 12px;padding:0 0 0 12px;display:flex;flex-direction:column;gap:7px;border-left:2px solid var(--rpg-mid)}
.student-sidebar .sidebar-submenu>a{display:flex!important;align-items:center!important;width:100%!important;min-height:38px!important;box-sizing:border-box;padding:8px 10px!important;margin:0!important;border:1px solid var(--rpg-mid)!important;border-radius:4px!important;background:var(--rpg-paper)!important;background-image:none!important;color:var(--rpg-ink)!important;box-shadow:none!important;font-size:12px!important;line-height:1.4!important;text-shadow:none!important;transform:none!important}
.student-sidebar .sidebar-submenu>.router-link-exact-active{background:var(--rpg-soft)!important;border-color:var(--rpg-edge)!important}
.sidebar-account-actions{display:flex;flex-direction:column;gap:10px;padding:14px 4px 4px 2px;border-top:1px solid var(--rpg-mid);flex:none}
@media(max-width:650px){.wallet{gap:5px;justify-content:flex-end;flex-wrap:wrap}.wallet>*{font-size:11px!important;padding:8px!important}.question-toolbar{gap:6px}.question-toolbar :deep(button),.question-toolbar>a{font-size:10px!important;padding:8px!important}.navigation-row{gap:8px;align-items:flex-start}.menu-toggle{min-width:0;font-size:11px;padding:9px}}
@media(max-width:600px){.question-toolbar>a,.question-toolbar :deep(.gift-center-launch),.question-toolbar :deep(.question-launch){height:36px!important;min-height:36px!important;padding:6px 9px!important;font-size:10px!important}}
@media(prefers-reduced-motion:reduce){.student-sidebar *{transition:none!important}}
</style>

<style scoped>
.student-sidebar .sidebar-menu-body>.sidebar-guide-link,.student-sidebar .sidebar-menu-body>.sidebar-guide-link:hover{background:var(--rpg-edge)!important;color:#fff!important;box-shadow:0 3px var(--rpg-shadow)!important;justify-content:center!important;gap:10px!important}.sidebar-guide-link img{width:88px;height:36px;object-fit:contain;flex:none}.sidebar-guide-link span{white-space:nowrap;font-weight:700}
</style>
